#!/usr/bin/env python3
# Гл. 7, пакет G: G0 (стыковки/счёт дней), G1 (крупные места), G2 (мелкие). assert count==1 на каждую замену.
import pathlib
p = pathlib.Path("03-manuscript/arc-02/ch-07.md")
t = p.read_text(encoding="utf-8")
n = 0
def rep(old, new):
    global t, n
    c = t.count(old); assert c == 1, f"count={c}: {old[:80]!r}"
    t = t.replace(old, new); n += 1

